=== FILE: skid_buffer.v ===
// skid_buffer.v
// Two-register valid/ready register slice (skid buffer).
// Implements interface_spec.md / microarchitecture.md (project prj-fed4b510c5).
//
//   m_valid / m_data       : output register
//   skid_valid / skid_data : skid register, always the newer of two beats
//   s_ready = !skid_valid  : inverse of a flop, no path from m_ready
//
// Next state (microarchitecture section 3), m_free = !m_valid || m_ready:
//   m_free and skid_valid      : output loads the skid beat, skid empties
//   m_free and skid empty      : output loads s_data, m_valid <= s_valid
//   !m_free and s_fire         : output holds, skid loads s_data
//   !m_free and no s_fire      : everything holds
`timescale 1ns / 1ps
`default_nettype none

module skid_buffer #(
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    reg             m_valid_d;
    reg [WIDTH-1:0] m_data_d;
    reg             skid_valid_d;
    reg [WIDTH-1:0] skid_data_d;

    wire m_free = !m_valid || m_ready;
    wire s_fire = s_valid && !skid_valid;

    assign s_ready = !skid_valid;

    // Next-state logic: every variable has a default, so no latch.
    always @* begin
        m_valid_d    = m_valid;
        m_data_d     = m_data;
        skid_valid_d = skid_valid;
        skid_data_d  = skid_data;
        if (m_free) begin
            if (skid_valid) begin
                m_valid_d    = 1'b1;
                m_data_d     = skid_data;
                skid_valid_d = 1'b0;
            end else begin
                m_valid_d = s_valid;
                m_data_d  = s_data;
            end
        end else if (s_fire) begin
            skid_valid_d = 1'b1;
            skid_data_d  = s_data;
        end
    end

    // Control registers: synchronous active-low reset drops every beat.
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else begin
            m_valid    <= m_valid_d;
            skid_valid <= skid_valid_d;
        end
    end

    // Data registers: not reset (microarchitecture section 2).
    always @(posedge clk) begin
        m_data    <= m_data_d;
        skid_data <= skid_data_d;
    end

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: skid_buffer_tb.v ===
// skid_buffer_tb.v
// Self-checking testbench for skid_buffer, lanes at WIDTH 8 and WIDTH 1.
// Top module: skid_buffer_tb.
//
// Timing (period 20 ns): stimulus is applied 4 ns after each rising edge;
// lane models update on the rising edge and check on the falling edge;
// 6 ns before each rising edge the inputs are flipped for 1 ns and the
// outputs must not move (registered-output / ready-path check).
//
// Lane check ids: 1 m_valid, 2 s_ready, 3 m_data (oldest), 4 hold.
// Top check ids: 1 glitch, 10-11 reset, 20-21 latency, 30-32 throughput,
// 40-45 stall, 50-52 stream with stalls, 60-64 reset with beats held,
// 70 full state reached in random traffic, 71 final drain.
`timescale 1ns / 1ps
`default_nettype none

module skid_buffer_tb_lane #(
    parameter integer W = 8
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         s_valid,
    input  wire [W-1:0] s_data,
    input  wire         m_ready,
    output wire         s_ready,
    output wire         m_valid,
    output wire [W-1:0] m_data,
    output wire [31:0]  held,
    output wire [31:0]  accepted,
    output wire [31:0]  delivered,
    output wire [31:0]  passed,
    output wire [31:0]  failed
);

    skid_buffer #(.WIDTH(W)) dut (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready),
        .s_data  (s_data),
        .m_valid (m_valid),
        .m_ready (m_ready),
        .m_data  (m_data)
    );

    // Reference model: a queue of up to two beats, moved only by the
    // handshakes the specification defines, computed from the stimulus.
    reg [31:0]  cnt        = 32'd0;
    reg [W-1:0] q0         = {W{1'b0}};
    reg [W-1:0] q1         = {W{1'b0}};
    reg [31:0]  acc_r      = 32'd0;
    reg [31:0]  del_r      = 32'd0;
    reg [31:0]  pass_r     = 32'd0;
    reg [31:0]  fail_r     = 32'd0;
    reg         seen_reset = 1'b0;
    reg         stall_q    = 1'b0;
    reg [W-1:0] stall_data = {W{1'b0}};
    reg         in_fire    = 1'b0;
    reg         out_fire   = 1'b0;

    assign held      = cnt;
    assign accepted  = acc_r;
    assign delivered = del_r;
    assign passed    = pass_r;
    assign failed    = fail_r;

    task chk(input ok, input integer id);
        begin
            if (ok) begin
                pass_r = pass_r + 32'd1;
            end else begin
                fail_r = fail_r + 32'd1;
                $error("skid_buffer_tb lane WIDTH=%0d: check %0d failed at %0t", W, id, $time);
            end
        end
    endtask

    always @(posedge clk) begin
        // Hold rule: a beat offered and not taken (pre-edge DUT values).
        stall_q    = rst_n && m_valid && !m_ready;
        stall_data = m_data;
        if (!rst_n) begin
            seen_reset = 1'b1;
            cnt        = 32'd0;
            acc_r      = 32'd0;
            del_r      = 32'd0;
        end else begin
            in_fire  = s_valid && (cnt < 32'd2);
            out_fire = m_ready && (cnt != 32'd0);
            if (out_fire) begin
                q0    = q1;
                cnt   = cnt - 32'd1;
                del_r = del_r + 32'd1;
            end
            if (in_fire) begin
                if (cnt == 32'd0) q0 = s_data;
                else              q1 = s_data;
                cnt   = cnt + 32'd1;
                acc_r = acc_r + 32'd1;
            end
        end
    end

    always @(negedge clk) begin
        if (seen_reset) begin
            chk(m_valid === (cnt != 32'd0), 1);
            chk(s_ready === (cnt < 32'd2), 2);
            if (cnt != 32'd0) chk(m_data === q0, 3);
            if (stall_q) chk((m_valid === 1'b1) && (m_data === stall_data), 4);
        end
    end

endmodule

module skid_buffer_tb;

    reg       clk     = 1'b0;
    reg       rst_n   = 1'b0;
    reg       s_valid = 1'b0;
    reg       m_ready = 1'b0;
    reg [7:0] s_data  = 8'h00;

    always #10 clk = ~clk;

    wire        l8_s_ready, l8_m_valid;
    wire [7:0]  l8_m_data;
    wire [31:0] l8_held, l8_acc, l8_del, l8_pass, l8_fail;
    wire        l1_s_ready, l1_m_valid;
    wire [0:0]  l1_m_data;
    wire [31:0] l1_held, l1_acc, l1_del, l1_pass, l1_fail;

    skid_buffer_tb_lane #(.W(8)) lane8 (
        .clk(clk), .rst_n(rst_n), .s_valid(s_valid), .s_data(s_data), .m_ready(m_ready),
        .s_ready(l8_s_ready), .m_valid(l8_m_valid), .m_data(l8_m_data),
        .held(l8_held), .accepted(l8_acc), .delivered(l8_del),
        .passed(l8_pass), .failed(l8_fail)
    );

    skid_buffer_tb_lane #(.W(1)) lane1 (
        .clk(clk), .rst_n(rst_n), .s_valid(s_valid), .s_data(s_data[0]), .m_ready(m_ready),
        .s_ready(l1_s_ready), .m_valid(l1_m_valid), .m_data(l1_m_data),
        .held(l1_held), .accepted(l1_acc), .delivered(l1_del),
        .passed(l1_pass), .failed(l1_fail)
    );

    reg [31:0]     passed = 32'd0;
    reg [31:0]     failed = 32'd0;
    reg [31:0]     tot_pass;
    reg [31:0]     tot_fail;
    reg [8*64-1:0] nonce = {(8*64){1'b0}};
    integer        ok;
    integer        i;
    integer        k;
    reg [31:0]     r;
    reg [7:0]      sd;
    reg [7:0]      nxt;
    reg            mr;
    reg            sv;
    reg            sr_now;
    reg [3:0]      sv_thr;
    reg [3:0]      mr_thr;
    reg [31:0]     astart;
    reg [31:0]     dstart;
    reg [31:0]     full_cycles = 32'd0;

    task check(input cond, input integer id);
        begin
            if (cond) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("skid_buffer_tb: check %0d failed at %0t", id, $time);
            end
        end
    endtask

    // One clock cycle: drive inputs at posedge+4, flip them for 1 ns at
    // posedge+14 (outputs must not move), restore, wait for the edge,
    // return at the next posedge+4 with the DUT updated.
    task step(input sv_i, input [7:0] sd_i, input mr_i);
        reg       sr8, mv8, sr1, mv1, md1;
        reg [7:0] md8;
        begin
            s_valid = sv_i;
            s_data  = sd_i;
            m_ready = mr_i;
            #10;
            sr8 = l8_s_ready; mv8 = l8_m_valid; md8 = l8_m_data;
            sr1 = l1_s_ready; mv1 = l1_m_valid; md1 = l1_m_data[0];
            s_valid = ~sv_i;
            m_ready = ~mr_i;
            s_data  = ~sd_i;
            #1;
            check((l8_s_ready === sr8) && (l8_m_valid === mv8) && (l8_m_data === md8) &&
                  (l1_s_ready === sr1) && (l1_m_valid === mv1) && (l1_m_data[0] === md1), 1);
            #1;
            s_valid = sv_i;
            s_data  = sd_i;
            m_ready = mr_i;
            @(posedge clk);
            #4;
        end
    endtask

    initial begin
        ok = $value$plusargs("nirmaan_nonce=%s", nonce);

        // ---- 1. Reset values ----
        rst_n = 1'b0;
        @(posedge clk);
        #4;
        step(1'b0, 8'h00, 1'b0);
        step(1'b1, 8'h55, 1'b0);
        check((l8_m_valid === 1'b0) && (l8_s_ready === 1'b1) &&
              (l1_m_valid === 1'b0) && (l1_s_ready === 1'b1) && (l8_held == 32'd0), 10);
        rst_n = 1'b1;
        step(1'b0, 8'h00, 1'b1);
        check((l8_m_valid === 1'b0) && (l8_s_ready === 1'b1) && (l1_m_valid === 1'b0), 11);

        // ---- 2. One-cycle latency ----
        step(1'b1, 8'hA1, 1'b1);
        check((l8_m_valid === 1'b1) && (l8_m_data === 8'hA1) && (l1_m_data === 1'b1) &&
              (l8_s_ready === 1'b1), 20);
        step(1'b0, 8'h00, 1'b1);
        check((l8_m_valid === 1'b0) && (l1_m_valid === 1'b0) && (l8_held == 32'd0), 21);

        // ---- 3. Full throughput, 32 beats back to back ----
        dstart = l8_del;
        for (i = 0; i < 32; i = i + 1) begin
            sd = 8'h10 + i[7:0];
            step(1'b1, sd, 1'b1);
            check((l8_m_valid === 1'b1) && (l8_s_ready === 1'b1) && (l8_m_data === sd) &&
                  (l1_m_valid === 1'b1) && (l1_m_data === sd[0:0]), 30);
        end
        step(1'b0, 8'h00, 1'b1);
        check((l8_del - dstart) == 32'd32, 31);
        check((l8_m_valid === 1'b0) && (l8_held == 32'd0), 32);

        // ---- 4. Stall: second beat accepted, third refused, ready rises ----
        astart = l8_acc;
        dstart = l8_del;
        step(1'b1, 8'hB0, 1'b0);
        check((l8_held == 32'd1) && (l8_m_valid === 1'b1) && (l8_s_ready === 1'b1) &&
              (l8_m_data === 8'hB0), 40);
        step(1'b1, 8'hB1, 1'b0);
        check((l8_held == 32'd2) && (l8_s_ready === 1'b0) && (l1_s_ready === 1'b0) &&
              (l8_m_data === 8'hB0), 41);
        step(1'b1, 8'hB2, 1'b0);
        step(1'b1, 8'hB2, 1'b0);
        check((l8_held == 32'd2) && (l8_s_ready === 1'b0) && (l8_m_data === 8'hB0) &&
              ((l8_acc - astart) == 32'd2), 42);
        step(1'b1, 8'hB2, 1'b1);
        check((l8_held == 32'd1) && (l8_s_ready === 1'b1) && (l8_m_data === 8'hB1), 43);
        step(1'b1, 8'hB2, 1'b1);
        check((l8_held == 32'd1) && (l8_m_valid === 1'b1) && (l8_m_data === 8'hB2), 44);
        step(1'b0, 8'h00, 1'b1);
        check((l8_m_valid === 1'b0) && ((l8_acc - astart) == 32'd3) &&
              ((l8_del - dstart) == 32'd3), 45);

        // ---- 5. Stream with a one-cycle stall and a four-cycle stall ----
        nxt = 8'h40;
        for (i = 0; i < 24; i = i + 1) begin
            mr = !((i == 4) || ((i >= 9) && (i <= 12)));
            sr_now = l8_s_ready;
            step(1'b1, nxt, mr);
            if (sr_now) nxt = nxt + 8'h01;
            if (i == 4)  check((l8_held == 32'd2) && (l8_s_ready === 1'b0), 50);
            if (i == 11) check((l8_held == 32'd2) && (l8_s_ready === 1'b0) &&
                               (l1_s_ready === 1'b0), 51);
        end
        for (k = 0; k < 3; k = k + 1) step(1'b0, 8'h00, 1'b1);
        check((l8_held == 32'd0) && (l8_acc == l8_del) && (l1_acc == l1_del), 52);

        // ---- 6. Reset with beats held ----
        step(1'b1, 8'hC0, 1'b0);
        step(1'b1, 8'hC1, 1'b0);
        check((l8_held == 32'd2) && (l8_s_ready === 1'b0), 60);
        rst_n = 1'b0;
        step(1'b1, 8'hC2, 1'b0);
        check((l8_m_valid === 1'b0) && (l8_s_ready === 1'b1) &&
              (l1_m_valid === 1'b0) && (l1_s_ready === 1'b1) && (l8_held == 32'd0), 61);
        rst_n = 1'b1;
        step(1'b0, 8'h00, 1'b1);
        check((l8_m_valid === 1'b0) && (l8_s_ready === 1'b1), 62);
        step(1'b1, 8'hC3, 1'b1);
        check((l8_m_valid === 1'b1) && (l8_m_data === 8'hC3), 63);
        step(1'b0, 8'h00, 1'b1);
        check((l8_m_valid === 1'b0) && (l8_held == 32'd0), 64);

        // ---- 7. Random traffic against the model, reset during traffic ----
        for (i = 0; i < 2000; i = i + 1) begin
            if (i < 500) begin
                sv_thr = 4'd12; mr_thr = 4'd12;
            end else if (i < 1000) begin
                sv_thr = 4'd15; mr_thr = 4'd4;
            end else if (i < 1500) begin
                sv_thr = 4'd4;  mr_thr = 4'd15;
            end else begin
                sv_thr = 4'd8;  mr_thr = 4'd8;
            end
            rst_n = !((i == 1200) || (i == 1201));
            r  = $random;
            sv = (r[3:0] < sv_thr);
            mr = (r[7:4] < mr_thr);
            step(sv, r[15:8], mr);
            if (l8_held == 32'd2) full_cycles = full_cycles + 32'd1;
        end
        rst_n = 1'b1;
        check(full_cycles != 32'd0, 70);

        // ---- 8. Drain ----
        for (k = 0; k < 4; k = k + 1) step(1'b0, 8'h00, 1'b1);
        check((l8_m_valid === 1'b0) && (l1_m_valid === 1'b0) &&
              (l8_held == 32'd0) && (l1_held == 32'd0) &&
              (l8_acc == l8_del) && (l1_acc == l1_del), 71);

        // ---- Verdict ----
        tot_pass = passed + l8_pass + l1_pass;
        tot_fail = failed + l8_fail + l1_fail;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, tot_pass, tot_fail);
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
